#!/usr/bin/env bash
# Regenerate notebooks/constraints.txt (pip constraints for the Colab notebook) from uv.lock.
#
#   bash scripts/export_constraints.sh            # rewrite the file
#   bash scripts/export_constraints.sh --check    # exit 1 when the file differs from uv.lock
#
# The file lists the runtime dependencies plus the data and plot extras, no dev tools and not
# the project itself. tests/test_constraints.py runs the check, so a lock change without a
# regenerated file fails CI.
set -euo pipefail

cd "$(dirname "$0")/.."
OUT=notebooks/constraints.txt

gen() {
  echo "# Generated by scripts/export_constraints.sh from uv.lock; do not edit."
  uv export --frozen --no-hashes --no-dev --no-emit-project --extra data --extra plot --no-header
}

if [ "${1:-}" = "--check" ]; then
  if ! gen | diff -u "$OUT" - >&2; then
    echo "$OUT is out of date: run bash scripts/export_constraints.sh" >&2
    exit 1
  fi
else
  gen > "$OUT"
  echo "wrote $OUT"
fi
